CREATE TABLE public.quality_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('complaints','surveys','education','improvements','invitation','response','consent','review_request','referral_request','recovery_request','standards')),payload jsonb NOT NULL DEFAULT '{}'::jsonb,version integer NOT NULL DEFAULT 1 CHECK(version>0),state text NOT NULL,owner_id uuid,assigned_user_id uuid,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.quality_items TO authenticated; GRANT ALL ON public.quality_items TO service_role; ALTER TABLE public.quality_items ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.quality_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_id uuid NOT NULL REFERENCES public.quality_items(id),actor_id uuid NOT NULL,action text NOT NULL,reason text NOT NULL,old_version integer NOT NULL,new_version integer NOT NULL,old_payload jsonb,new_payload jsonb NOT NULL,request_key text NOT NULL,request_hash text NOT NULL,result jsonb NOT NULL,at timestamptz NOT NULL DEFAULT now(),UNIQUE(actor_id,request_key));
GRANT SELECT ON public.quality_audit TO authenticated; GRANT ALL ON public.quality_audit TO service_role; ALTER TABLE public.quality_audit ENABLE ROW LEVEL SECURITY;
CREATE INDEX quality_items_kind_owner ON public.quality_items(kind,owner_id,state); CREATE INDEX quality_audit_entity ON public.quality_audit(entity_id,at);
CREATE FUNCTION public.quality_has_invitation(_survey uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.quality_items WHERE kind='invitation' AND owner_id=auth.uid() AND payload->>'surveyId'=_survey::text AND state IN ('OPEN','ANSWERED') AND (payload->>'expiresAt')::timestamptz>now()); $$;
REVOKE ALL ON FUNCTION public.quality_has_invitation(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.quality_has_invitation(uuid) TO authenticated;
CREATE POLICY quality_read ON public.quality_items FOR SELECT TO authenticated USING(public.is_director(auth.uid()) OR (public.is_ops(auth.uid()) AND kind IN ('complaints','improvements','review_request','referral_request','recovery_request','standards')) OR (assigned_user_id=auth.uid() AND kind IN ('complaints','education','improvements')) OR (owner_id=auth.uid() AND kind IN ('complaints','consent','invitation','response','review_request','referral_request')) OR (kind='education' AND state='PUBLISHED' AND (payload->>'validUntil')::timestamptz>=now()) OR (kind='surveys' AND state='PUBLISHED' AND public.quality_has_invitation(id)));
CREATE POLICY quality_audit_read ON public.quality_audit FOR SELECT TO authenticated USING(public.is_director(auth.uid()) OR EXISTS(SELECT 1 FROM public.quality_items qi WHERE qi.id=entity_id AND (qi.assigned_user_id=auth.uid() OR (public.is_ops(auth.uid()) AND qi.kind IN ('complaints','improvements')))));
COMMENT ON TABLE public.quality_items IS 'Internal quality authority; no delivery, appointment mutation, charge or refund. Legacy generic records remain drafts.';